@main enum Tests {
    static var count=0
    static func check(_ value:@autoclosure()->Bool,_ message:String){count+=1;if !value(){fatalError("archive post regression: "+message)}}
    static func id(_ value:Int32,peer:Int64=1,namespace:Int32=0)->MessageId{MessageId(peerId:PeerId(peer),namespace:namespace,id:value)}
    static func main() throws {
        let folder=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true)
        defer{try? FileManager.default.removeItem(at:folder)}
        let archive=Archive(path:folder.appendingPathComponent("archive.json").path)
        let one=id(1),two=id(2),other=id(3),foreign=id(1,peer:2)
        let info=NagramiXArchivedForwardInfo(StoreMessageForwardInfo(authorId:PeerId(77),sourceId:PeerId(78),sourceMessageId:id(99,peer:78),date:50,authorSignature:"signature",psaType:nil,flags:MessageForwardInfo.Flags(rawValue:1)))
        archive.add(one,group:88,text:"caption",media:["photo1"],forward:info)
        archive.add(two,group:88,text:"",media:["photo2"])
        archive.add(other,group:99,text:"unrelated",media:["photo2"])
        archive.add(foreign,group:88,text:"other chat",media:["foreign"],deleted:true)
        let tx=Transaction();tx.messages=[one:archive.rendered(one),two:archive.rendered(two),other:archive.rendered(other)];tx.groups[one]=[tx.messages[one]!,tx.messages[two]!]
        check(archive.postMessageIds(messageIds:[one],messages:Array(tx.messages.values)) == [one,two],"whole album selection, scoped away from other peer and post")
        let first=archive.postDeletionPlan(transaction:tx,messageIds:[one],localCandidates:[])
        check(first.nativeMessageIds==[one,two] && first.localMessageIds.isEmpty,"first deletion archives the full native post")
        let planner=EnginePlanner(archive,tx)
        var planned:NagramiXArchivePostDeletionPlan?
        _ = planner.nagramiXArchivePostDeletionPlan(messageIds:[one],localCandidates:[]).startStandalone(next:{planned=$0})
        check(planned?.nativeMessageIds==[one,two] && planned?.liveMessageIds==[one,two],"actual engine wrapper returns the complete native group and live permission IDs")
        let scoped=Archive(path:folder.appendingPathComponent("scope.json").path)
        scoped.add(one,group:88,text:"one",media:[],thread:1)
        scoped.add(two,group:88,text:"two",media:[],thread:1)
        scoped.add(other,group:88,text:"other topic",media:[],thread:2)
        scoped.add(id(1,namespace:3),group:88,text:"other namespace",media:[],thread:1)
        check(scoped.postMessageIds(messageIds:[one],messages:[])==[one,two],"equal keys in other namespaces and topics stay isolated")
        check(nagramiXWholePostMessages(scoped.rendered(one),messages:[scoped.rendered(one),scoped.rendered(two),scoped.rendered(other),scoped.rendered(id(1,namespace:3)),archive.rendered(foreign)]).map(\.id)==[one,two],"context payload includes only the focused complete post in original order")
        archive.mark([one,two]);tx.messages.removeValue(forKey:one);tx.messages.removeValue(forKey:two);tx.groups.removeAll()
        check(first.localMessageIds.isEmpty,"server removal while confirmation is open cannot change frozen first phase")
        let rendered=archive.rendered(one)
        check(rendered.groupingKey==88 && archive.rendered(two).groupingKey==88,"real native helper drops grouping but final archive renderer restores it")
        check(rendered.text=="caption" && rendered.media.map(\.name)==["photo1"],"caption and media retain identity and order")
        check(rendered.forwardInfo?.source?.id==PeerId(78) && rendered.forwardInfo?.authorSignature=="signature","forward source and author metadata survive rendering")
        let candidates=archive.localPostDeletionCandidates(messages:[rendered,archive.rendered(two)])
        check(candidates==[one,two],"all-deleted displayed post permits local removal")
        let second=archive.postDeletionPlan(transaction:tx,messageIds:[one],localCandidates:candidates)
        check(second.nativeMessageIds.isEmpty && second.localMessageIds==[one,two],"repeat delete targets only complete local post")
        _ = planner.nagramiXArchivePostDeletionPlan(messageIds:[one],localCandidates:candidates).startStandalone(next:{planned=$0})
        check(planned?.localMessageIds==[one,two] && planned?.liveMessageIds.isEmpty==true,"engine wrapper keeps local copies out of native permission requests")
        _ = EnginePlanner(nil,tx).nagramiXArchivePostDeletionPlan(messageIds:[one],localCandidates:candidates).startStandalone(next:{planned=$0})
        check(planned?.nativeMessageIds==[one] && planned?.localMessageIds.isEmpty==true,"absent archive registration falls back to native deletion without a purge")
        let late=archive.reserveLate(one)
        archive.purge(second.localMessageIds);archive.queue.drain()
        check(archive.saved.records.count==2 && archive.saved.records.values.allSatisfy{$0.messageId != one && $0.messageId != two},"only chosen post removed")
        check(archive.mediaStore.files.contains("photo2") && !archive.mediaStore.files.contains("photo1"),"shared attachment remains owned by unrelated post")
        check(archive.rejectLate(one,late),"late producer cannot resurrect a purged ID")
        let restored=Archive(path:archive.path);restored.restore()
        check(restored.saved.purgedMessageKeys?.count==2 && restored.saved.records.count==2,"selective purge and tombstones survive restart")
        let ticketBefore=restored.mediaStore.sequence
        restored.refresh(one);restored.queue.drain()
        check(restored.saved.records.count==2 && restored.mediaStore.sequence==ticketBefore,"actual capture queue cannot reserve or resurrect a purged ID after restart")
        let captureRace=Archive(path:folder.appendingPathComponent("capture-race.json").path)
        captureRace.add(one,group:nil,text:"saved",media:["saved"],deleted:true)
        captureRace.refresh(one);captureRace.purge([one]);captureRace.queue.drain()
        check(captureRace.saved.records.isEmpty && captureRace.mediaStore.owners.isEmpty,"queued capture before purge barrier is rejected and cannot recreate records or owners")
        // A partly deleted album is still a first-stage post while any sibling is live.
        let partial=Archive(path:folder.appendingPathComponent("partial.json").path)
        partial.add(one,group:44,text:"caption",media:["a"],deleted:true);partial.add(two,group:44,text:"",media:["b"])
        let live=partial.rendered(two)
        let native=Message(stableId:live.stableId,stableVersion:0,id:live.id,globallyUniqueId:nil,groupingKey:live.groupingKey,groupInfo:nil,threadId:nil,timestamp:live.timestamp,flags:live.flags,tags:0,globalTags:0,localTags:[],customTags:[],forwardInfo:nil,author:live.author,text:live.text,attributes:[],media:live.media,peers:live.peers,associatedMessages:SimpleDictionary(),associatedMessageIds:[],associatedMedia:[:],associatedThreadInfo:nil,associatedStories:[:])
        let partialTx=Transaction();partialTx.messages[two]=native
        let partialCandidates=partial.localPostDeletionCandidates(messages:[partial.rendered(one),native])
        check(partialCandidates.isEmpty,"displayed partly live post never approves a purge")
        let partialPlan=partial.postDeletionPlan(transaction:partialTx,messageIds:[one],localCandidates:[one])
        check(partialPlan.localMessageIds.isEmpty && partialPlan.nativeMessageIds==[one,two],"retain old caption when deleting remaining native media")
        partial.add(other,group:nil,text:"old post",media:[],deleted:true)
        let mixed=partial.postDeletionPlan(transaction:partialTx,messageIds:[one,other],localCandidates:[one,other])
        check(mixed.localMessageIds==[other] && mixed.nativeMessageIds==[one,two],"mixed selection freezes each post phase separately")
        partialTx.messages.removeAll()
        let raced=partial.postDeletionPlan(transaction:partialTx,messageIds:[one,two],localCandidates:partialCandidates)
        check(raced.localMessageIds.isEmpty,"late server deletion of a partly live selected post does not authorize purge")
        // OFF never expands a native selection or requests local removal.
        NagramiXMessageArchiveSettings.current.showDeletedMessages=false
        let off=partial.postDeletionPlan(transaction:partialTx,messageIds:[one],localCandidates:[one])
        check(off.nativeMessageIds==[one] && off.localMessageIds.isEmpty,"OFF preserves native deletion")
        NagramiXMessageArchiveSettings.current.showDeletedMessages=true
        // Atomic-write failure preserves published copies AND their files.
        let failure=Archive(path:folder.appendingPathComponent("fail/archive.json").path)
        try FileManager.default.createDirectory(atPath:folder.appendingPathComponent("fail").path,withIntermediateDirectories:true)
        failure.add(one,group:nil,text:"keep",media:["keep"],deleted:true)
        try FileManager.default.removeItem(at:folder.appendingPathComponent("fail"));try Data([0]).write(to:folder.appendingPathComponent("fail"))
        failure.purge([one]);failure.queue.drain()
        check(failure.saved.records.count==1 && failure.mediaStore.files.contains("keep"),"failed purge does not destroy visible data or bytes")
        let rejected=failure.reserveLate(one);check(failure.rejectLate(one,rejected),"late reservation is rejected during failed commit")
        check(failure.mediaStore.files.contains("keep"),"rejected reservation cannot prune published bytes before durable commit")
        try FileManager.default.removeItem(at:folder.appendingPathComponent("fail"));try FileManager.default.createDirectory(at:folder.appendingPathComponent("fail"),withIntermediateDirectories:true)
        failure.retry()
        check(failure.saved.records.isEmpty && failure.mediaStore.files.isEmpty,"retry durably removes selected copy and late reservation")
        let uiArchive=Archive(path:folder.appendingPathComponent("ui.json").path)
        uiArchive.add(one,group:55,text:"caption",media:["u1"]);uiArchive.add(two,group:55,text:"",media:["u2"])
        let ui=UIHost(uiArchive)
        ui.chatDisplayNode.historyNode.groups[one]=[uiArchive.rendered(one),uiArchive.rendered(two)]
        check(Set(ui.nagramiXPostSelectionIds([one]))==[one,two],"real UI selection helper selects entire post")
        NagramiXMessageArchiveSettings.current.showDeletedMessages=false
        check(ui.nagramiXPostSelectionIds([one])==[one],"OFF retains exact native selection")
        NagramiXMessageArchiveSettings.current.showDeletedMessages=true
        for subject:ChatControllerSubject in [.pinnedMessages,.scheduledMessages,.messageOptions] {
            ui.presentationInterfaceState.subject=subject
            check(ui.nagramiXPostSelectionIds([one])==[one],"special views do not expand archive selection")
        }
        ui.presentationInterfaceState.subject=nil;ui.nagramiXReadHistoryDisabled=true
        check(ui.nagramiXPostSelectionIds([one])==[one],"readonly preview does not gain archive actions")
        ui.nagramiXReadHistoryDisabled=false
        let firstUI=NagramiXArchivePostDeletionPlan(nativeMessageIds:[one,two],localMessageIds:[])
        ui.chatDisplayNode.historyNode.ignoreMessageIds=[foreign]
        ui.nagramiXDeleteArchivedPostsWithUndo(plan:firstUI,type:.forLocalPeer)
        check(ui.chatDisplayNode.historyNode.ignoreMessageIds==[one,two,foreign],"pending deletion hides complete post without overwriting another pending selection")
        check(ui.context.engine.messages.requests.isEmpty,"Undo does not submit deletion early")
        _ = ui.undo!.action(.undo)
        check(ui.chatDisplayNode.historyNode.ignoreMessageIds==[foreign] && uiArchive.saved.records.count==2,"Undo leaves both original snapshots intact")
        ui.nagramiXDeleteArchivedPostsWithUndo(plan:firstUI,type:.forLocalPeer)
        _ = ui.undo!.action(.commit)
        check(ui.context.engine.messages.requests==[[one,two]],"first commit sends only the frozen native post")
        check(ui.chatDisplayNode.historyNode.ignoreMessageIds==[foreign],"first archived copies are not permanently hidden by ignoreMessageIds")
        let secondUI=NagramiXArchivePostDeletionPlan(nativeMessageIds:[],localMessageIds:[one,two])
        ui.nagramiXDeleteArchivedPostsWithUndo(plan:secondUI,type:.forLocalPeer)
        _ = ui.undo!.action(.undo);uiArchive.queue.drain()
        check(uiArchive.saved.records.count==2,"Undo of a local purge removes no records")
        ui.nagramiXDeleteArchivedPostsWithUndo(plan:secondUI,type:.forLocalPeer)
        _ = ui.undo!.action(.commit)
        check(uiArchive.saved.records.count==2,"local purge waits for archive queue and durable commit")
        uiArchive.queue.drain()
        check(uiArchive.saved.records.isEmpty && ui.chatDisplayNode.historyNode.ignoreMessageIds==[foreign],"local commit removes whole post and releases temporary hiding")
        check(ui.context.engine.messages.requests.count==1,"second-stage purge never submits a native deletion request")
        partial.clearAll();partial.queue.drain()
        check(partial.saved.records.isEmpty && partial.mediaStore.files.isEmpty,"full clear removes all records and media")
        let clearFail=Archive(path:folder.appendingPathComponent("clear/archive.json").path)
        try FileManager.default.createDirectory(at:folder.appendingPathComponent("clear"),withIntermediateDirectories:true)
        clearFail.add(one,group:nil,text:"saved",media:["clear"],deleted:true)
        try FileManager.default.removeItem(at:folder.appendingPathComponent("clear"));try Data([0]).write(to:folder.appendingPathComponent("clear"))
        clearFail.clearAll();clearFail.queue.drain()
        check(clearFail.saved.records.count==1 && clearFail.mediaStore.files.contains("clear"),"failed full clear preserves visible records and bytes")
        let clearLate=clearFail.reserveLate(one)
        check(clearFail.rejectLate(one,clearLate),"late reservation during failed full clear is rejected")
        try FileManager.default.removeItem(at:folder.appendingPathComponent("clear"));try FileManager.default.createDirectory(at:folder.appendingPathComponent("clear"),withIntermediateDirectories:true)
        clearFail.retry()
        check(clearFail.saved.records.isEmpty && clearFail.mediaStore.owners.isEmpty && clearFail.mediaStore.files.isEmpty,"full clear retry removes even reservations newer than global barrier")
        // Legacy Codable payloads have neither forward metadata nor tombstones.
        let legacy=Data("{\"records\":{}}".utf8)
        let decoded=try JSONDecoder().decode(NagramiXMessageArchiveState.self,from:legacy)
        check(decoded.records.isEmpty && decoded.purgedMessageKeys==nil,"legacy JSON remains decodable")
        print("\(count) real archive post planning/render/purge/persistence checks passed; Postbox codec/media and signal delivery are boundaries")
    }
}
